SELECT d.*,
       EXISTS(SELECT 1 FROM cinema c WHERE c.directory_id = d.id) AS linked
FROM cinema_directory d

    AND d.name LIKE CONCAT('%', #{name}, '%')
    AND d.province = #{province}
    AND d.city = #{city}
    AND d.district = #{district}
    AND d.brand = #{brand}


            AND EXISTS(SELECT 1 FROM cinema lc WHERE lc.directory_id = d.id)
            AND NOT EXISTS(SELECT 1 FROM cinema lc WHERE lc.directory_id = d.id)



ORDER BY d.id DESC

SELECT poi_id FROM cinema_directory
WHERE poi_id IN
#{id}

SELECT * FROM cinema_directory
WHERE id IN
#{id}
